    function get_current_marketing_lang(bool $fresh = false): string
    {
        static $current = null;
        if (!$fresh && $current !== null) {
            return $current;
        }

        $supported = get_supported_marketing_languages();

        // 1. URL Query parameter (?lang=es)
        if (!empty($_GET['lang'])) {
            $candidate = strtolower(trim($_GET['lang']));
            if (array_key_exists($candidate, $supported)) {
                $current = $candidate;
                if (!headers_sent()) {
                    @setcookie('pos_marketing_lang', $candidate, time() + (86400 * 365), '/');
                }
                return $current;
            }
        }

        // 2. Cookie
        if (!empty($_COOKIE['pos_marketing_lang'])) {
            $candidate = strtolower(trim($_COOKIE['pos_marketing_lang']));
            if (array_key_exists($candidate, $supported)) {
                $current = $candidate;
                return $current;
            }
        }

        // 3. Browser HTTP_ACCEPT_LANGUAGE
        if (!empty($_SERVER['HTTP_ACCEPT_LANGUAGE'])) {
            $browserLang = substr($_SERVER['HTTP_ACCEPT_LANGUAGE'], 0, 2);
            if (array_key_exists($browserLang, $supported)) {
                $current = $browserLang;
                return $current;
            }
        }

        $current = 'en';
        return $current;
    }

    function is_marketing_rtl(?string $lang = null): bool
    {
        $l = $lang ?: get_current_marketing_lang();
        $supported = get_supported_marketing_languages();
        return !empty($supported[$l]['rtl']);
    }

