    function __t(string $key, ?string $fallback = null, ?string $forceLang = null): string
    {
        $lang = $forceLang ?: get_current_marketing_lang();
        if ($lang === 'en') {
            return $fallback ?? $key;
        }

        $table = get_marketing_translations_table();
        if (isset($table[$key][$lang]) && $table[$key][$lang] !== '') {
            return $table[$key][$lang];
        }

        return $fallback ?? $key;
    }
